-- Add Dense Passage Retrieval method, introduced in arXiv 2004.04906. The source paper
-- gets the source evidence row (Introduced banner); citers are linked by
-- link_papers_by_source_citations.py and the hourly reference backfill.

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'dense-passage-retrieval',
    'Dense Passage Retrieval',
    'Dense Passage Retrieval (DPR)',
    'Dense Passage Retrieval (DPR) retrieves passages for open-domain question answering with learned dense embeddings instead of sparse term matching. Two independent [BERT](/methods/bert) encoders map questions and passages into the same vector space, relevance is the inner product of their embeddings, and the whole corpus is indexed for maximum inner product search. The encoders are trained with a contrastive loss using in-batch negatives plus a hard negative passage retrieved by [BM25](/methods/bm25). Trained on only a few thousand to tens of thousands of question-passage pairs, DPR beat a strong Lucene-BM25 system by 9-19% absolute in top-20 passage retrieval accuracy and improved end-to-end QA on several benchmarks. DPR is the standard dense-retriever baseline and the retriever used by [RAG](/methods/rag); late-interaction models such as [ColBERT](/methods/colbert) are a related alternative.',
    'dense passage retrieval, dense passage retriever, DPR retriever',
    (
        SELECT id
        FROM areas
        WHERE name = 'Language'
        LIMIT 1
    ),
    2020,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2004.04906'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Dense Passage Retrieval for Open-Domain Question Answering',
    'https://github.com/facebookresearch/DPR',
    NULL,
    '[Dense Passage Retrieval for Open-Domain Question Answering](/paper/2004.04906)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id
FROM methods
WHERE slug = 'dense-passage-retrieval'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source'
FROM methods
WHERE slug = 'dense-passage-retrieval'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

